"""Generate the DFIR follow-up report from immutable live traces, without API calls."""
import collections, datetime, hashlib, html, json, statistics
from pathlib import Path
from dfir_cases import CASES, SOURCES, ACTIONS
from dfir_eval import ROOT, OUT

esc=lambda x:html.escape(str(x))
pretty=lambda x:esc(json.dumps(x,indent=2))
ratio=lambda n,d:f'{n}/{d} ({100*n/d:.1f}%)' if d else 'not scored'

def main():
    summary=json.loads((OUT/'results/summary.json').read_text())
    # Narrative below is an adjudicated write-up of this immutable run. Refuse to
    # silently reuse its conclusions with new data even if counts happen to match.
    if {Path(p).name for p in summary['paths']} != {'20261004T064722Z-replay.jsonl','20261004T064809Z-agentic.jsonl'}:
        raise SystemExit('This report narrative is pinned to the original DFIR run. Review new results and version the report before rebuilding.')
    rows=[json.loads(l) for p in summary['paths'] for l in Path(p).read_text().splitlines() if l]
    replay=[r for r in rows if 'step' not in r and 'score' in r]
    agentic=[r for r in rows if 'step' in r]
    finals=[r for r in agentic if r.get('final')]
    plan=json.loads((OUT/'evidence/frozen-plan.json').read_text())
    raw_scores=[r['response']['answers']['action_'+a]['noul'] for r in replay for a in r['score']['unsupported_actions']]
    sensitivity=[]
    for threshold in (.5,.8,.9):
        m=collections.Counter()
        for r in replay:
            chosen={k for k in ACTIONS if r['response']['answers']['action_'+k]['noul']>=threshold}
            required=set(r['gold']['required']);allowed=required|set(r['gold']['optional'])
            m['exact_sets']+=not(required-chosen or chosen-allowed)
            m['unsupported_actions']+=len(chosen-allowed);m['missed_actions']+=len(required-chosen)
        sensitivity.append(dict(threshold=threshold,**m))
    analysis={'post_hoc_only':True,'original_frozen_threshold':.5,'threshold_sensitivity':sensitivity,
              'unsupported_score_range':[min(raw_scores),max(raw_scores)],'unsupported_score_median':statistics.median(raw_scores),
              'agentic_incident_completion':{'n':sum(r['kind']=='temporal' for r in finals),'complete':sum(r['kind']=='temporal' and r.get('complete_retrieval',False) for r in finals)},
              'agentic_benign_completion':{'n':sum(r['kind']=='benign' for r in finals),'complete':sum(r['kind']=='benign' and r.get('complete_retrieval',False) for r in finals)}}
    (OUT/'results/diagnostics.json').write_text(json.dumps(analysis,indent=2))
    variants=''.join(f'<tr><th>{esc(v)}</th><td>{ratio(m["triage_correct"],m["n"])}</td><td>{ratio(m["action_set_correct"],m["n"])}</td><td>{ratio(m["claims_correct"],m["claims_total"])}</td><td>{m["unsupported_actions"]}</td></tr>' for v,m in summary['variants'].items())
    stages=[]
    for label,predicate in [('Early alert only',lambda c:c['kind']=='temporal' and c['phase']==1),('Confirmed / later snapshots',lambda c:c['kind']=='temporal' and c['phase']>1),('Decisive evidence withheld',lambda c:c['kind']=='ablation'),('Verified benign controls',lambda c:c['kind']=='benign')]:
        ids={c['id'] for c in CASES if predicate(c)};rs=[r for r in replay if r['case_id'] in ids]
        stages.append(f'<tr><th>{label}</th><td>{len(ids)}</td><td>{len(rs)}</td><td>{ratio(sum(r["score"]["action_set_correct"] for r in rs),len(rs))}</td></tr>')
    source_blocks=[]
    for key,src in SOURCES.items():
        source_blocks.append(f'<details><summary>{key} · {esc(src["title"])} <span>{src["date"]}</span></summary><p><a href="{esc(src["url"])}" target="_blank" rel="noreferrer">Read the public report</a></p><ol>'+''.join(f'<li>{esc(f[1])} <small>Source section: {esc(f[0])}</small></li>' for f in src['facts'].values())+f'</ol><p class="muted">{esc(src["caveat"])}</p></details>')
    cases=[]
    for c in CASES:
        rs=[r for r in replay if r['case_id']==c['id']];m=summary['cases'][c['id']]
        fail=any(not(r['score']['triage_correct'] and r['score']['action_set_correct'] and all(r['score']['claim_correct'].values())) for r in rs)
        brief='; '.join(sorted({', '.join(r['score']['unsupported_actions'])+' unsupported' for r in rs if r['score']['unsupported_actions']}))
        if not brief:brief='all action sets matched'
        if any(r['score']['missed_claims'] for r in rs):brief+='; credential extraction claim missed in reordered input'
        case_table=''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in [r['variant'],r['repeat']+1,r['response']['answers']['triage']['choice'],', '.join(r['score']['selected_actions']) or 'none',', '.join(r['score']['unsupported_actions']) or '—',', '.join(r['score']['missed_claims']) or '—'])+'</tr>' for r in rs)
        cases.append(f'<details class="case" data-source="{c["source"]}" data-result="{"fail" if fail else "pass"}"><summary>{c["id"]} · {esc(c["kind"])} · observation cutoff {c["phase"]}<span>{m["action_set_correct"]}/{m["n"]} action sets</span></summary><p>{esc(brief)}</p><p>Required: <code>{esc(", ".join(c["gold"]["required"]) or "none")}</code>. Optional: <code>{esc(", ".join(c["gold"]["optional"]) or "none")}</code>.</p><div class="scroll"><table><thead><tr><th>Variant</th><th>Repeat</th><th>Triage</th><th>Selected actions</th><th>Unsupported</th><th>Missed claim</th></tr></thead><tbody>{case_table}</tbody></table></div><details><summary>Observations and source provenance</summary><pre>{pretty({"model_state":c["state"],"local_gold_not_sent":c["gold"],"local_provenance_not_sent":c["provenance"]})}</pre></details><details><summary>Actual baseline response</summary><pre>{pretty(rs[0]["response"])}</pre></details></details>')
    traces=[]
    for r in finals:
        episode=[x for x in agentic if x['case_id']==r['case_id'] and x['variant']==r['variant']]
        trace=' → '.join(x['chosen_tool'] for x in episode)
        inspected=[{'step':x['step'],'reviewed_sources':x['reviewed_sources'],'chosen_tool':x['chosen_tool'],
                    'triage':x['response']['answers']['triage'],'request_observation_ids':[e['id'] for e in x['request']['state']['observations']],
                    'tool_result':x.get('tool_result'),'complete_retrieval':x.get('complete_retrieval')} for x in episode]
        traces.append(f'<details><summary>{r["case_id"]} · {r["variant"]} · {"complete" if r["complete_retrieval"] else "premature finish"}<span>{len(episode)} calls</span></summary><p><code>{esc(trace)}</code></p><pre>{pretty(inspected)}</pre></details>')
    sensitivity_table=''.join(f'<tr><td>{d["threshold"]:.1f}</td><td>{ratio(d["exact_sets"],len(replay))}</td><td>{d["unsupported_actions"]}</td><td>{d["missed_actions"]}</td></tr>' for d in sensitivity)
    action_html=''.join(f'<tr><th>{k}</th><td><code>{esc(a["target"])}</code></td><td>{esc(a["proposal"])}</td></tr>' for k,a in ACTIONS.items())
    evidence_links=''.join(f'<li><a href="results/{Path(p).name}">{Path(p).name}</a> · complete request/response trace</li>' for p in summary['paths'])
    stats=summary['replay'];ag=summary['agentic']
    template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jev × DFIR Report · SOC evaluation</title><style>
    :root{color-scheme:light;--ink:#12262f;--muted:#52636a;--teal:#126d69;--paper:#f3f5f2;--line:#ccd8d4;--red:#953f2a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:44px 28px 80px}nav{display:flex;gap:24px;margin-bottom:36px;font-size:14px}a{color:var(--teal);text-underline-offset:3px}h1{font-size:clamp(32px,5vw,57px);line-height:1.06;letter-spacing:-.04em;max-width:900px;margin:14px 0 22px}h2{font-size:26px;margin:42px 0 14px;letter-spacing:-.02em}p{max-width:970px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;font-weight:750;color:var(--teal)}.lead{font-size:20px;max-width:920px}.callout{border-left:5px solid var(--red);background:#fff2ea;padding:18px 24px;margin:28px 0}.callout p{margin:0}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:28px 0}.card{border:1px solid var(--line);border-radius:12px;background:#fff;padding:20px}.card strong{display:block;font-size:34px;letter-spacing:-.04em}.card span{font-size:13px;color:var(--muted)}table{border-collapse:collapse;width:100%;font-size:14px;background:#fff}th,td{text-align:left;padding:13px 15px;border-bottom:1px solid var(--line);vertical-align:top}thead{background:#e3ece7}td:first-child,th:first-child{padding-left:18px}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px}small{display:block;color:var(--muted);font-size:12px}.muted{color:var(--muted)}details{border:1px solid var(--line);background:#fff;border-radius:9px;padding:13px 18px;margin:10px 0}summary{cursor:pointer;font-weight:650}summary span{float:right;font-weight:450;color:var(--muted);font-size:13px}details details{background:#f7f9f6}pre{overflow:auto;max-height:480px;font-size:12px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere;background:#edf2f0;padding:16px;border-radius:6px}code{font-size:.9em}.filters{display:flex;align-items:end;gap:18px;flex-wrap:wrap;margin:18px 0}label{font-size:13px;font-weight:650}select,input{display:block;padding:10px;border:1px solid #91aaa0;border-radius:6px;background:white;color:var(--ink);font:inherit;margin-top:5px}.tag{display:inline-block;border-radius:20px;background:#e0eee5;color:#1d544a;padding:3px 12px;font-size:12px;margin-right:8px}footer{border-top:1px solid var(--line);margin-top:44px;padding-top:18px;color:var(--muted);font-size:13px}[hidden]{display:none!important}li{margin-bottom:8px}@media(max-width:700px){main{padding:24px 16px 50px}.cards{grid-template-columns:1fr 1fr}.card{padding:14px}.card strong{font-size:29px}summary span{float:none;display:block}nav{gap:16px;flex-wrap:wrap}th,td{padding:10px}h2{font-size:23px}}
    </style></head><body><main><nav><a href="../report.html">Original synthetic evaluation</a><a href="#cases">Inspect cases</a><a href="#sources">Source reports</a><a href="#evidence">Evidence</a></nav>
    <div class="eyebrow">Jev 1.13.0 · DFIR follow-up · RUN_DATE</div><h1>Real incident patterns.<br>Decisions at the evidence cutoff.</h1>
    <p class="lead">36 reconstructed fixtures from six public DFIR Report articles, tested through 216 replays and 24 read-only investigations. <strong>268 live API calls.</strong> This follow-up supports analyst-reviewed use; it does not qualify Jev for autonomous containment.</p>
    <div class="cards"><div class="card"><strong>100%</strong><span>216/216 acceptable triage decisions</span></div><div class="card"><strong>67.1%</strong><span>145/216 exact containment sets at frozen 0.5 cutoff</span></div><div class="card"><strong>99.5%</strong><span>645/648 evidence-claim decisions</span></div><div class="card"><strong>58.3%</strong><span>14/24 investigations read all evidence</span></div></div>
    <div class="callout"><p><strong>The operational gap is uncertainty handling.</strong> In 71 of 72 early or evidence-withheld replays, the separate action score supported restricting the alerted host despite insufficient evidence under the frozen policy. In 10 of 12 incident investigations, Jev read endpoint evidence and then stopped before reviewing lateral scope and response records. All 12 benign investigations completed.</p></div>
    <p><span class="tag">No false closures</span><span class="tag">No benign containment</span><span class="tag">No destructive or provider-wide recommendations</span></p>
    <p class="muted">These are reconstructed, anonymized observations—not raw victim logs. Source behavior is mapped to report sections. Host identities, ordinal clocks, corroboration details, asset criticality, benign controls, withheld feeds and expected decisions are authored. API inference is hosted; orchestration and evidence are local. No production response was executed.</p>
    <h2>What the new cases test</h2><p>Each incident has four observation cutoffs, a paired case with decisive evidence withheld, and a benign counterfactual with simulated owner and telemetry verification. The model sees no article title, URL, source label, expected answer or future observation. The same hypothetical action menu is used across all cases, so a named target in a proposal is not proof it is compromised.</p>
    <div class="scroll"><table><thead><tr><th>Case group</th><th>Fixtures</th><th>Replays</th><th>Exact action sets</th></tr></thead><tbody>STAGES</tbody></table></div>
    <p>Containment is scored as a set of target-specific recommendations: foothold, exposed identity, lateral host, exfiltration job, persistence and malicious policy. Neighboring critical infrastructure, wiping and broad provider blocks are separate negative choices. Claims distinguish executed encryption, confirmed business-file exfiltration and completed credential extraction from alerts, access attempts and tool capabilities.</p>
    <h2>Replay results</h2><div class="scroll"><table><thead><tr><th>Variant</th><th>Triage</th><th>Exact action set</th><th>Evidence claims</th><th>Unsupported actions</th></tr></thead><tbody>VARIANTS</tbody></table></div>
    <p>Baseline, reordered observations/questions/choices, and attacker-controlled instruction text were each repeated twice. Repeats and variants are correlated measurements, not 216 independent incidents. Triage uses frozen acceptable sets, including escalation when critical-service judgment is appropriate.</p>
    <p>All 108 replays with corroborated or later incident evidence selected an acceptable full containment set. All 36 verified benign controls closed without containment. The 71 action mismatches were confined to host restrictions on early or evidence-withheld cases. These violated this bench’s evidence prerequisite; some organizations may separately permit precautionary access restriction as hardening. The distinction requires human policy adjudication.</p>
    <p>Three reordered ActiveMQ snapshots missed the credential-extraction claim. None asserted unsupported encryption, bulk exfiltration or credential extraction. 68 action selections conflicted with an “investigate” triage answer. Raw per-question outputs therefore need cross-answer consistency checks.</p>
    <h2>Higher thresholds trade one error for another</h2><p>The frozen yes/no threshold was 0.5. Unsupported host-restriction scores ranged from 0.50 to 0.77 (median 0.64), so these were not high-confidence recommendations. The following is an <strong>exploratory analysis of the same responses after seeing results</strong>, not a new held-out validation or revised passing score.</p>
    <div class="scroll"><table><thead><tr><th>Action threshold</th><th>Exact sets</th><th>Unsupported action selections</th><th>Missed required action selections</th></tr></thead><tbody>SENSITIVITY</tbody></table></div>
    <p>Raising the threshold to 0.8 removes the premature selections but misses 76 required action selections. A threshold alone does not solve the workflow. Keep evidence completeness, target verification, critical-service review and cross-answer consistency in deterministic orchestration; calibrate any operating threshold on separate SOC data.</p>
    <h2>Agentic investigations: completion matters</h2><p>Jev chose local read-only evidence packs. Twelve incident/control scenarios ran both normally and with injected text: 24 episodes and 52 calls. It was explicitly asked to review all offered sources before the final handoff. <strong>14/24 completed; 10/24 stopped early.</strong> Only 2/12 incident episodes completed, compared with 12/12 benign episodes. The completed episodes had correct final triage, action sets and claims (14/14); reporting only that subset would hide the main failure.</p>
    <p>Early finishes were the five non-RDP incident families under both variants. Jev stopped after the endpoint pack, leaving identity/lateral and response records unread. Provisional outputs are retained but excluded from final classification accuracy. Tool selection and completeness are tested here; optimal retrieval cost, actual connector behavior and real containment are not.</p>TRACES
    <h2 id="cases">Inspect every fixture</h2><div class="filters"><label>Source family<select id="source"><option value="all">All sources</option>SOURCE_OPTIONS</select></label><label>Result<select id="result"><option value="all">All cases</option><option value="fail">Has a mismatch</option><option value="pass">All matched</option></select></label><label>Search<input id="search" type="search" placeholder="A3, benign, ablation…"></label><span id="shown" aria-live="polite"></span></div>CASES
    <h2 id="sources">Public sources and adaptation boundaries</h2>SOURCES
    <p>The public articles provide behavioral anchors and observed chronology. They do not provide every normalized record in these fixtures. In particular, the ActiveMQ article assesses credential theft from memory access and later reuse; fixture A3 adds explicit dump-content corroboration to create a controlled extraction test. Asset criticality, absence of change approval and exact identity/job mappings are benchmark additions throughout. Benign controls are counterfactual and never attributed to the incident reports. Snapshot A4 is an authored recovery review; F excludes the parallel investigation’s BYOVD chain.</p>
    <h2>Containment catalog and review</h2><p>This wording is authored by the bench; Jev scores whether each proposal fits the evidence. No prose rationale is attributed to Jev. The last three choices are scope/safety probes. Any operational adaptation needs evidence capture, exact target readback, dependency review, approval, action verification and rollback.</p><div class="scroll"><table><thead><tr><th>ID</th><th>Exact target</th><th>Candidate recommendation</th></tr></thead><tbody>ACTIONS</tbody></table></div><p><a href="containment-review.json">Preservation, verification and rollback notes for the six legitimate action types</a></p>
    <h2>Decision and limitations</h2><p><strong>Continue with supervised triage and analyst-reviewed recommendations.</strong> The frozen 95% exact-action-set and investigation-completion criteria failed. The broad triage and evidence-claim checks passed. The earlier synthetic report’s autonomy restriction remains appropriate.</p>
    <p>These six selected reports overrepresent Windows ransomware intrusions. They do not establish real-world prevalence, false-positive rates, probability calibration, multilingual robustness, production latency or performance on unseen attacks. Public-report training contamination cannot be ruled out. Labels come from one author, structured evidence is much cleaner than raw SOC telemetry, and baseline benign controls are explicit. No conclusions about real isolation reliability or recovery follow from this test.</p>
    <h2 id="evidence">Evidence and reproducibility</h2><ul>EVIDENCE_LINKS<li><a href="evidence/frozen-plan.json">Frozen source-linked cases, policy and acceptance criteria</a> · SHA-256 <code>PLAN_HASH</code></li><li><a href="evidence/sources.json">Six source retrieval records and content hashes</a></li><li><a href="results/summary.json">Scored live results</a> and <a href="results/diagnostics.json">exploratory threshold diagnostics</a></li><li><a href="evidence/local-tests.txt">40 passing validation and data-separation tests</a></li><li><a href="README.txt">Rerun commands, provenance and limitations</a></li></ul>
    <p>All 268 responses reported <code>jev-1.13.0</code>, with zero observed API/schema errors or retries. 1,259,028 input tokens imply about <strong>$0.0529</strong> at the previously verified $0.042/M input-token rate; this is a usage estimate, not settled billing. Median request latency was 148 ms; p95 was 228 ms. <a href="https://docs.typesafe.ai/models">Vendor model/pricing reference</a>.</p>
    <footer>Local evaluation · Frozen before model calls · All inference traces preserved · Source content treated as data · No production actions or malware execution</footer></main>
    <script>const source=document.querySelector('#source'),result=document.querySelector('#result'),search=document.querySelector('#search');function filterCases(){let n=0;document.querySelectorAll('.case').forEach(el=>{const visible=(source.value==='all'||el.dataset.source===source.value)&&(result.value==='all'||el.dataset.result===result.value)&&el.textContent.toLowerCase().includes(search.value.toLowerCase());el.hidden=!visible;if(visible)n++});document.querySelector('#shown').textContent=n+' of 36 fixtures'}[source,result,search].forEach(el=>el.addEventListener('input',filterCases));filterCases();</script></body></html>'''
    replacements={'RUN_DATE':rows[0]['time'][:10]+' UTC','STAGES':''.join(stages),'VARIANTS':variants,'SENSITIVITY':sensitivity_table,'TRACES':''.join(traces),'SOURCE_OPTIONS':''.join(f'<option value="{k}">{k} · {esc(s["title"].split(":")[0])}</option>' for k,s in SOURCES.items()),'CASES':''.join(cases),'SOURCES':''.join(source_blocks),'ACTIONS':action_html,'EVIDENCE_LINKS':evidence_links,'PLAN_HASH':(OUT/'evidence/frozen-plan.sha256').read_text().strip()}
    # Uppercase replacement tokens do not occur in appended untrusted JSON values.
    for token,value in replacements.items():template=template.replace(token,value)
    (OUT/'report.html').write_text(template)
    print('Built',OUT/'report.html',len(template),'characters')

if __name__=='__main__':main()
